import"chrome://resources/js/jstemplate_compiled.js";import{assert}from"chrome://resources/js/assert.js";import{addWebUiListener}from"chrome://resources/js/cr.js";const invalidationCountersMap={};function refreshInvalidationCountersDisplay(){const invalidationCountersArray=[];Object.keys(invalidationCountersMap).sort().forEach((function(t){invalidationCountersArray.push({type:t,count:invalidationCountersMap[t].count,time:invalidationCountersMap[t].time})}));const table=document.querySelector("#invalidation-counters-table");assert(table);jstProcess(new JsEvalContext({rows:invalidationCountersArray}),table)}function appendToLog(logMessage){const invalidationsLog=document.querySelector("#invalidations-log");assert(invalidationsLog);invalidationsLog.value+="["+(new Date).getTime()+"] "+logMessage+"\n"}function onInvalidationReceived(types){const logMessage="Received invalidation for "+types.join(", ");appendToLog(logMessage);for(const type of types){if(!(type in invalidationCountersMap)){invalidationCountersMap[type]={count:0,time:""}}++invalidationCountersMap[type].count;invalidationCountersMap[type].time=(new Date).toTimeString()}refreshInvalidationCountersDisplay()}function onLoad(){addWebUiListener("onInvalidationReceived",onInvalidationReceived);refreshInvalidationCountersDisplay()}document.addEventListener("DOMContentLoaded",onLoad,false);